-- Migration 003: counting-method version CM-1 (cited by every published statistic).
INSERT INTO counting_method VALUES ('CM-1',
'SHOT = continuous camera take, cut to cut (dissolve = boundary). SCENE = continuous narrative unit in one location and continuous story time; new scene on location change or time jump; montage = one scene tagged MONTAGE; cross-cut strands = separate scenes; flashback/dream = separate scene. VISIBLE SCREEN TIME = union of human-confirmed, identity-Confirmed intervals with mode visible or speaking_on_screen within one annotation set; partial visibility counts when the face or identifying body/costume is in frame and the character is identifiable without dialogue context; back-of-head-only or doubles (stunt credits) count only if the scene context makes the character unambiguous, and are tagged in evidence. Voice-offscreen, archival, depiction and mention are counted separately and never in visible time. Characters sharing a shot each receive the full overlap. Counts are PROVISIONAL unless coverage spans the whole asset.');
